    return _.flatten(map(function(e1) {
      var K = e1.t[0];
      return _.flatten(map(function(e2) {
        var M = e2.t[0];
        return _.flatten(map(function(I) {
          return [['ends', [K, I], and([e1.v, e2.v, coin(0.99)])]];
        }, _.range(0, M + 1)));
      }, _.values(target)));
    }, _.values(place)));
  })()
