var replacement = relation({}, instances_replacement);

var replacement_by_1 = index(replacement, [0]);
var instances_written = [].concat(
  // written(K,C,C) :- in(K,C), \+ replaced(K).
  (function() {
    return _.flatten(map(function(e1) {
      var K = e1.t[0];
      var C = e1.t[1];
      return [['written', [K, C, C], and([e1.v, not(holds(replaced, [K]))])]];
    }, _.values(in_)));
  })(),
  // written(K,C,D) :- in(K,C), replaced(K), replacement(K,D).
  (function() {
    return _.flatten(map(function(e1) {
      var K = e1.t[0];
      var C = e1.t[1];
      return _.flatten(map(function(e2) {
        return _.flatten(map(function(e3) {
          var D = e3.t[1];
          return [['written', [K, C, D], and([e1.v, e2.v, e3.v])]];
        }, (replacement_by_1[keyOf([K])] || [])));
      }, probe(replaced, [K])));
    }, _.values(in_)));
  })()
