var ins_by_1_3 = index(ins, [0, 2]);
var ins_by_1 = index(ins, [0]);
var out_by_1 = index(out, [0]);
// pert/2: recursive; the rules applied in stages from no tuple, each
// reading the stage before, until a stage adds no tuple and the stages number the tuples
