            var I = e3.t[1];
            return [['pert', [N, I], and([e1.v, e2.v, e3.v])]];
          }, (ins_by_1_3[keyOf([N, M])] || [])));
        }, _.values(target)));
      }, _.values(input)));
    })(),
    // pert(K,I) :- in(K,_), deleted(K), K1 is K + 1, pert(K1,I).
    (function() {
      return _.flatten(map(function(e1) {
        var K = e1.t[0];
        var K1 = (K + 1);
        return _.flatten(map(function(e2) {
          return _.flatten(map(function(e3) {
            var I = e3.t[1];
            return [['pert', [K, I], and([e1.v, e2.v, e3.v])]];
          }, (pert_by_1[keyOf([K1])] || [])));
        }, probe(deleted, [K])));
      }, _.values(in_)));
    })(),
    // pert(K,I) :- in(K,C), \+ deleted(K), ins(K,I,J), out(J,D), written(K,C,D), J1 is J + 1, K1 is K + 1, pert(K1,J1).
    (function() {
      return _.flatten(map(function(e1) {
        var K = e1.t[0];
        var C = e1.t[1];
        var K1 = (K + 1);
        return _.flatten(map(function(e2) {
          var I = e2.t[1];
          var J = e2.t[2];
          var J1 = (J + 1);
          return _.flatten(map(function(e3) {
            var D = e3.t[1];
            return _.flatten(map(function(e4) {
              return _.flatten(map(function(e5) {
                return [['pert', [K, I], and([e1.v, not(holds(deleted, [K])), e2.v, e3.v, e4.v, e5.v])]];
              }, probe(pert, [K1, J1])));
            }, probe(written, [K, C, D])));
          }, (out_by_1[keyOf([J])] || [])));
        }, (ins_by_1[keyOf([K])] || [])));
      }, _.values(in_)));
    })()
