  var size = sum(map(function(r) { return _.size(r); }, rels));
  return stage < size || size !== before ? stages_pert(stage_pert(rels), stage + 1, size) : rels;
};
var rels_pert = stages_pert([{}], 0, -1);
var pert = rels_pert[0];

var instances_perturbed = [].concat(
  // perturbed :- pert(0,0).
  (function() {
    return _.flatten(map(function(e1) {
      return [['perturbed', [], e1.v]];
    }, probe(pert, [0, 0])));
  })()
);
var perturbed = relation({}, instances_perturbed);

// component 0 bool
var model = function() {
  return [holds(perturbed, [])()];
};
Infer({method: 'enumerate'}, model);

