        }, _.values(at)));
      }, _.values(demand_6)));
    })(),
    // demand_6(V) :- demand_6(Min), at(I,V), V >= Min, D is V - Min, step(I,0,D), I1 is I + 1.
    (function() {
      return _.flatten(map(function(e1) {
        var Min = e1.t[0];
        return _.flatten(map(function(e2) {
          var I = e2.t[0];
          var V = e2.t[1];
          if (V >= Min) {
            var D = (V - Min);
            var I1 = (I + 1);
            return _.flatten(map(function(e3) {
              return [['demand_6', [V], yes]];
            }, probe(step, [I, 0, D])));
          } else {
            return [];
          }
        }, _.values(at)));
      }, _.values(demand_6)));
    })(),
    // demand_6(0).
    (function() {
      return [['demand_6', [0], yes]];
    })()
  );
  var next_demand_4 = relation({}, only('demand_4', instances_demand_4));
  var next_demand_6 = relation({}, only('demand_6', instances_demand_4));
  var next_step = relation({}, only('step', instances_demand_4));
  return [next_demand_4, next_demand_6, next_step];
};
var stages_demand_4 = function(rels, stage, before) {
  var size = sum(map(function(r) { return _.size(r); }, rels));
  return stage < size || size !== before ? stages_demand_4(stage_demand_4(rels), stage + 1, size) : rels;
};
var rels_demand_4 = stages_demand_4([{}, {}, {}], 0, -1);
var demand_4 = rels_demand_4[0];
var demand_6 = rels_demand_4[1];
var step = rels_demand_4[2];

var instances_demand_5 = [].concat(
  // demand_5(V) :- demand_6(Min), at(I,V), V >= Min, D is V - Min, step(I,0,D), I1 is I + 1.
  (function() {
    return _.flatten(map(function(e1) {
      var Min = e1.t[0];
      return _.flatten(map(function(e2) {
        var I = e2.t[0];
        var V = e2.t[1];
        if (V >= Min) {
          var D = (V - Min);
          var I1 = (I + 1);
          return _.flatten(map(function(e3) {
            return [['demand_5', [V], yes]];
          }, probe(step, [I, 0, D])));
        } else {
          return [];
        }
      }, _.values(at)));
    }, _.values(demand_6)));
  })(),
  // demand_5(0).
  (function() {
    return [['demand_5', [0], yes]];
  })()
);
var demand_5 = relation({}, instances_demand_5);

var elements = elements_facts;

var instances_ends = [].concat(
  // 0.5::ends(I) :- elements(N), between(0,N,I).
  (function() {
    return _.flatten(map(function(e1) {
      var N = e1.t[0];
      return _.flatten(map(function(I) {
        return [['ends', [I], and([e1.v, coin(0.5)])]];
      }, _.range(0, N + 1)));
    }, _.values(elements)));
  })()
