// list/2: recursive; the rules applied in stages from no tuple, each
// reading the stage before, until a stage adds no tuple and the stages number the tuples
var stage_list = function(rels) {
  var list = rels[0];
  var instances_list = [].concat(
    // list(N,Anon1) :- demand_5(Anon1), elements(N), ends(N).
    (function() {
      return _.flatten(map(function(e1) {
        var Anon1 = e1.t[0];
        return _.flatten(map(function(e2) {
          var N = e2.t[0];
          return _.flatten(map(function(e3) {
            return [['list', [N, Anon1], and([e1.v, e2.v, e3.v])]];
          }, probe(ends, [N])));
        }, _.values(elements)));
      }, _.values(demand_5)));
    })(),
    // list(I,Min) :- demand_6(Min), at(I,V), \+ ends(I), V >= Min, D is V - Min, step(I,0,D), I1 is I + 1, list(I1,V).
    (function() {
      return _.flatten(map(function(e1) {
        var Min = e1.t[0];
        return _.flatten(map(function(e2) {
          var I = e2.t[0];
          var V = e2.t[1];
          if (V >= Min) {
